#!/usr/bin/env node
/**
 * TRED — deux verrous pour que le tuteur ne nie plus jamais tes documents.
 *
 *     node <chemin>\tred-garde-documents.mjs
 *
 * Le correctif precedent etait une INSTRUCTION dans le prompt. Rien
 * n'empechait qu'on la reecrive, ni que le modele l'ignore. Voici les deux
 * garanties qui manquaient.
 *
 * VERROU 1 — tests/tutor-prompt.test.ts   (13 tests)
 *
 *   `buildTutorAgent` est une fonction pure : elle assemble un texte. Ces
 *   tests verifient ce que ce texte DIT. Preuve qu'ils servent : en remettant
 *   l'ancien code fautif, 9 des 13 tombent. En le retirant, 13/13 passent.
 *
 *   Ils garantissent qu'aucune version du prompt ne pourra plus affirmer
 *   "l'etudiant n'a rien televerse" quand il a televerse.
 *
 * VERROU 2 — lib/denial-guard.ts + 10 tests
 *
 *   Un test hors ligne ne peut rien contre un modele qui desobeit a une
 *   instruction correcte. Ce garde lit la REPONSE reellement produite. S'il y
 *   trouve un deni d'acces alors que des documents etaient fournis, il
 *   journalise et ECRIT UN SIGNALEMENT dans content_report -- qui apparait
 *   dans "Gemeldete Antworten" sur ta page d'administration.
 *
 *   Il ne reecrit rien : le texte est deja a l'ecran, le corriger en cours de
 *   route serait pire. Il rend la panne VISIBLE au lieu de silencieuse.
 *
 *   La distinction qui decide de tout : "cette information ne figure pas dans
 *   tes documents" est LEGITIME et ne declenche rien. Nier l'ACCES ou
 *   l'EXISTENCE declenche. Cinq tests servent uniquement a prouver que le
 *   garde se tait sur les reponses correctes -- un garde trop bavard finit
 *   non lu, et un garde non lu ne garde rien.
 *
 *   Il se tait aussi quand il n'y a vraiment aucun document : la meme phrase
 *   devient vraie. Il juge un ECART avec la realite, pas des mots.
 *
 * Plus un script `test` dans packages/web : `bun run --cwd packages/web test`.
 * 106 tests passent aujourd'hui.
 *
 * Aucune migration -- content_report existe deja (ou sera creee par
 * migre-base.mjs).
 */
import { writeFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

function racine() {
  const departs = [process.cwd(), dirname(fileURLToPath(import.meta.url))];
  for (const depart of departs) {
    let d = depart;
    for (let i = 0; i < 8; i++) {
      if (existsSync(join(d, "packages", "web", "package.json"))) return d;
      const p = dirname(d);
      if (p === d) break;
      d = p;
    }
  }
  return null;
}

const ROOT = racine();
if (!ROOT) { console.error("\n  x  Depot introuvable.\n"); process.exit(1); }

const FILES = {
"packages/web/src/api/agent/index.ts": "",
"packages/web/src/api/index.ts": "",
"packages/web/src/api/lib/denial-guard.ts": "",
"packages/web/tests/tutor-prompt.test.ts": "",
"packages/web/tests/denial-guard.test.ts": "",
"packages/web/package.json": ""
};
for (const [rel, b64] of Object.entries(FILES)) {
  const cible = join(ROOT, rel);
  mkdirSync(dirname(cible), { recursive: true });
  writeFileSync(cible, Buffer.from(b64, "base64"));
  console.log("  ecrit  " + rel);
}

console.log(`
  Verifie :   bun run --cwd packages/web test
  Attendu :   106 pass, 0 fail

  Si un jour quelqu'un casse le prompt, ce sont les tests qui le diront --
  pas un etudiant devant son ecran.
`);
